UPDATE ec_internal_pages SET intro_content='[{"_type":"block","_key":"ke3","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ke2","text":"Earwax removal, also called ear cleaning, is an in-office service that clears extra wax from the ear canal to restore comfort and clearer sound.","marks":[]}]},{"_type":"block","_key":"ke5","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ke4","text":"Built-up wax can cause muffled hearing, ringing, pressure, and poor hearing aid performance, and professional removal protects the ear.","marks":[]}]},{"_type":"block","_key":"ke7","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ke6","text":"New Leaf Hearing Care provides earwax removal in Arvada, CO and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"ke9","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"ke8","text":"Earwax cleaning is a simple service that can make a big change fast. When wax builds up, sound gets blocked, and the ear can feel full or sore.","marks":[]}]},{"_type":"block","_key":"keb","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kea","text":"New Leaf Hearing Care offers safe, professional ear cleaning in Colorado. The Littleton office is formerly known as Columbine Hearing Care and is now part of New Leaf Hearing Care.","marks":[]}]}]' WHERE id='01KVFZWBZ2DWSMYGFTGNF592MZ' AND intro_content='[{"_type":"block","_key":"ke3","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ke2","text":"Earwax removal is an in-office service that clears extra wax from the ear canal to restore comfort and clearer sound.","marks":[]}]},{"_type":"block","_key":"ke5","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ke4","text":"Built-up wax can cause muffled hearing, ringing, pressure, and poor hearing aid performance, and professional removal protects the ear.","marks":[]}]},{"_type":"block","_key":"ke7","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ke6","text":"New Leaf Hearing Care provides earwax removal in Arvada, CO and Littleton, CO.","marks":[]}]},{"_type":"block","_key":"ke9","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"ke8","text":"Earwax removal is a simple service that can make a big change fast. When wax builds up, sound gets blocked, and the ear can feel full or sore.","marks":[]}]},{"_type":"block","_key":"keb","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kea","text":"New Leaf Hearing Care offers safe, professional earwax removal in Colorado. The Littleton office is formerly known as Columbine Hearing Care and is now part of New Leaf Hearing Care.","marks":[]}]}]';
